// Scam warnings ported from the Autonomous Job Kit (lib/jobkit/redflags.py): the kit's own test cases,
// a parity table against results the Python produced, and the full parity fixtures
// (tests/fixtures/jobkit/eligibility/parity.json and postings.json, generated by running the Python).
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const RF = require('../../packages/core/redflags');

const FIX = path.join(__dirname, '..', 'fixtures', 'jobkit', 'eligibility');
const PARITY = JSON.parse(fs.readFileSync(path.join(FIX, 'parity.json'), 'utf8'));
const POSTINGS = JSON.parse(fs.readFileSync(path.join(FIX, 'postings.json'), 'utf8')).postings;

const FILLER = (' You will analyse data, prepare reports and work with the team. Requirements include strong communication ' +
  'skills and attention to detail. Responsibilities cover planning, testing and documentation.').repeat(3);
const flags = (text, opts) => RF.redFlags(text + FILLER, opts).map((f) => f.flag);

// ---- the kit's RedFlagTests ----------------------------------------------------------------------------------

test('kit: each kind of warning fires on a plain example', () => {
  const cases = [
    ['A refundable training fee of $150 is required before you start.', 'pay'],
    ['You will receive a cheque to purchase your home office equipment from our approved vendor.', 'cheque'],
    ['Please contact our hiring manager on Telegram: @hrdesk to schedule your interview.', 'chat app'],
    ['Interviews are conducted via WhatsApp only.', 'chat app'],
    ['Salary will be paid in Bitcoin every week.', 'crypto'],
    ['No interview needed, you will be hired immediately.', 'interview'],
    ["Send a copy of your driver's license and your SSN with your application.", 'SIN/SSN'],
    ['Please respond within 24 hours to secure your position.', 'pressure'],
  ];
  for (const [text, word] of cases) {
    const got = flags(text, { company: 'Acme Corp', role: 'Analyst' });
    assert.ok(got.some((g) => g.toLowerCase().includes(word.toLowerCase())), `${text} -> ${JSON.stringify(got)}`);
  }
});

test('kit: personal email addresses', () => {
  assert.ok(flags('Send your resume to acme.hr.dept@gmail.com today.', { company: 'Acme Corp' }).length);
  assert.ok(flags('Questions? Write to jane.doe@outlook.com', { company: 'Acme', system: 'greenhouse' }).length);
  // a small business on Job Bank using its own gmail is normal
  assert.deepEqual(flags('Send your resume to roaringrolls@gmail.com', { company: 'The Roaring Rolls', system: 'jobbank' }), []);
});

test('kit: very high pay for unskilled entry-level work', () => {
  let got = RF.redFlags('Data entry clerk wanted, no experience. Earn $45/hour from home.', { role: 'Data Entry Clerk' });
  assert.ok(got.map((g) => g.flag).includes('pay far above normal for unskilled entry-level work'));
  assert.deepEqual(flags('Pay: $45/hour.', { role: 'Senior Software Engineer' }), []);
  assert.deepEqual(flags('Pay: $22/hour.', { role: 'Data Entry Clerk' }), []);
  got = RF.redFlags('Virtual assistant, beginners welcome, £35 per hour.' + FILLER, { role: 'Virtual Assistant' });
  assert.ok(got.some((g) => g.flag.includes('pay far above')));
});

test('kit: very short, vague description', () => {
  assert.ok(RF.redFlags('Work from home. Great pay. Apply now.').map((g) => g.flag).includes('very short, vague description'));
});

test('kit: reassurances, payroll lines and trade phrases do not flag', () => {
  const safe = [
    'We will never ask you to pay a fee or for your bank details during the hiring process.',
    'There is no application fee.',
    'Employees are paid biweekly by direct deposit or check.',
    'Experience building Telegram bots and WhatsApp Business API integrations is a plus.',
    "Must have a valid driver's license.",
    'A background check and SSN are collected for Form I-9 after an offer is accepted.',
    'We are hiring immediately. Immediate start available.',
    'Our signal processing team builds radar systems and sends data through Signal pipelines.',
    'Company-provided laptop and equipment; we reimburse your home office setup.',
    'Beware of recruitment fraud: we never ask candidates to buy equipment or pay fees.',
    'Applications close within 2 weeks of posting.',
  ];
  for (const text of safe) {
    assert.deepEqual(flags(text, { company: 'Acme Corp', role: 'Software Engineer', system: 'greenhouse' }), [], text);
  }
});

test('kit: the quote shows the matching sentence', () => {
  const got = RF.redFlags('Pay the $99 registration fee to start.' + FILLER);
  assert.match(got[0].quote, /registration fee/);
});

test('kit: a real Job Bank posting has no warnings', () => {
  const p = POSTINGS.find((x) => x.name === 'jobbank');
  assert.deepEqual(RF.redFlags(p.description, { company: p.company, role: p.role, system: 'jobbank' }), []);
});

// ---- sentences and quotes ------------------------------------------------------------------------------------

test('splitSentences: bullets dropped, abbreviations kept whole', () => {
  assert.deepEqual(RF.splitSentences('- We are a U.S. company. Ph.D. preferred! Apply now.\n2) Second line\n\n• Third, e.g. this one.'),
    ['We are a U.S. company.', 'Ph.D. preferred!', 'Apply now.', 'Second line', 'Third, e.g. this one.']);
  assert.deepEqual(RF.splitSentences('Line one\r\nLine two? "Quoted" next.'), ['Line one', 'Line two?', '"Quoted" next.']);
  assert.deepEqual(RF.splitSentences(''), []);
  assert.deepEqual(RF.splitSentences(null), []);
});

test('long sentences are quoted around the match', () => {
  const text = 'You will ' + 'very '.repeat(80) + 'carefully pay the training fee of $300, which is charged at the end of this ' +
    'unusually long sentence that keeps going and going so the quote has to be shortened around the match.';
  const [f] = RF.redFlags(text);
  assert.equal(f.flag, 'asks you to pay (fee, training, equipment or a check)');
  assert.ok(f.quote.startsWith('...very') && f.quote.endsWith('...'));
  assert.match(f.quote, /training fee of \$300/);
  assert.ok(f.quote.length <= 176); // at most 170 characters plus the two ellipses
});

test('words are counted the Python (Unicode) way', () => {
  // ASCII-only \w would split "idéal", "Montréal" ... into extra words.
  const [f] = RF.redFlags('Le candidat idéal parle français et anglais. Résumé requis. Rémunération compétitive à Montréal, Québec.');
  assert.deepEqual(f, { flag: 'very short, vague description', quote: 'only 14 words' });
});

