test('parity table: same flags as the Python on representative sentences', () => {
  assert.ok(TABLE.length >= 25);
  for (const [text, filler, opts, expected] of TABLE) {
    assert.deepEqual(RF.redFlags(text + (filler ? FILLER : ''), opts).map((f) => f.flag), expected, text);
  }
});

test('parity fixtures: identical flags and quotes to the Python', () => {
  assert.equal(PARITY.filler, FILLER);
  assert.ok(PARITY.redflags.length >= 25);
  for (const c of PARITY.redflags) {
    const got = RF.redFlags(c.text + (c.filler ? FILLER : ''), { company: c.company, role: c.role, system: c.system });
    assert.deepEqual(got, c.expected, c.text);
  }
});

test('parity fixtures: real postings split and flag the same as the Python', () => {
  assert.equal(POSTINGS.length, 9);
  for (const p of POSTINGS) {
    assert.deepEqual(RF.splitSentences(p.description), p.expected.sentences, p.name);
    assert.deepEqual(RF.redFlags(p.description, { company: p.company, role: p.role, system: p.system }), p.expected.flags, p.name);
  }
});

test('loads as a browser global (CoreRedFlags)', () => {
  const ctx = { self: {} };
  vm.runInNewContext(fs.readFileSync(require.resolve('../../packages/core/redflags'), 'utf8'), ctx);
  assert.equal(typeof ctx.self.CoreRedFlags.redFlags, 'function');
  assert.deepEqual([...ctx.self.CoreRedFlags.redFlags('Pay the $99 registration fee to start.' + FILLER).map((f) => f.flag)],
    ['asks you to pay (fee, training, equipment or a check)']);
});
